-- FaceDissolveRepository.getPeopleHealth
select
  "person"."personGroupId" as "id",
  "person"."name",
  "person"."ownerId",
  count("asset_face"."id") as "faceCount",
  count("asset_face"."id") filter (
    where
      "asset_face"."sourceType" = $1
  ) as "exif",
  count("asset_face"."id") filter (
    where
      "asset_face"."sourceType" = $2
  ) as "machineLearning",
  count("asset_face"."id") filter (
    where
      "asset_face"."sourceType" = $3
  ) as "manual",
  count("asset_face"."id") filter (
    where
      not exists (
        select
          1 as "one"
        from
          "face_search"
        where
          "face_search"."faceId" = "asset_face"."id"
      )
  ) as "facesWithoutEmbedding"
from
  "person"
  left join "asset_face" on "asset_face"."personGroupId" = "person"."personGroupId"
where
  not EXISTS (
    SELECT
    FROM
      "person_pet"
    WHERE
      "person_pet"."personGroupId" = "person"."personGroupId"
  )
  and "person"."ownerId" = $4
group by
  "person"."personGroupId",
  "person"."name",
  "person"."ownerId"
order by
  "exif" desc,
  "person"."personGroupId" asc
limit
  $5
offset
  $6
select
  count(*) as "count"
from
  "person"
where
  not EXISTS (
